WordHunterWoW_ENDesc_Item[109156] = "Use: Increases Strength by 6 for 1 hour. Counts as both a Battle and Guardian elixir.  This effect persists through death. (3 Sec Cooldown)"
WordHunterWoW_ENDesc_Item[109160] = "Use: Increases Stamina by 9 for 1 hour. Counts as both a Battle and Guardian elixir.  This effect persists through death. (3 Sec Cooldown)"
