WordHunterWoW_ENDesc_Item[109167] = "Use: Adds this toy to your Toy Box.\n\nRetrieves the loot from a nearby corpse. Can only be used in Draenor.  (3 Sec Cooldown)"
WordHunterWoW_ENDesc_Item[109171] = "Use: Allows you to look far into the distance."
WordHunterWoW_ENDesc_Item[109172] = "Use: Allows you to look far into the distance."
WordHunterWoW_ENDesc_Item[109173] = "Use: Allows you to look far into the distance."
WordHunterWoW_ENDesc_Item[109174] = "Use: Allows you to look far into the distance."
WordHunterWoW_ENDesc_Item[109183] = "Use: Adds this toy to your Toy Box.\n\nShrinks the entire world for 5 min or until you attack. (15 Min Cooldown)"
WordHunterWoW_ENDesc_Item[109184] = "Use: Cloaks the user in a stealth field for as long as they stand still. Cannot be used in combat. The field lasts for up to 6 sec. after moving.\n\nThe Stealthman shares a cooldown with non-healing potions.  Ineffective above level 49. (5 Min Cooldown)"
WordHunterWoW_ENDesc_Item[109196] = "Use: Place a Battle-Worn Frostwolf Banner upon the corpses of slain thunderlords within the Ribbreaker Warcamp. (2 Sec Cooldown)"
WordHunterWoW_ENDesc_Item[109217] = "Use: Increases your Agility by 23 for 25 sec. (5 Min Cooldown)"
WordHunterWoW_ENDesc_Item[109218] = "Use: Increases your Intellect by 23 for 25 sec. (5 Min Cooldown)"
WordHunterWoW_ENDesc_Item[109219] = "Use: Increases your Strength by 23 for 25 sec. (5 Min Cooldown)"
WordHunterWoW_ENDesc_Item[109220] = "Use: Increases your Versatility by 6 for 25 sec. (5 Min Cooldown)"
WordHunterWoW_ENDesc_Item[109221] = "Use: Puts the imbiber in an elevated state of focus where they can restore up to 10 mana over 10 sec, but they are defenseless until their focus is broken. (5 Min Cooldown)"
WordHunterWoW_ENDesc_Item[109222] = "Use: Restores 1 mana. (5 Min Cooldown)"
WordHunterWoW_ENDesc_Item[109223] = "Use: Restores 3 health. (5 Min Cooldown)"
WordHunterWoW_ENDesc_Item[109224] = "Use: Combine the soul shards at the forge in Gul'var to create Gul'dan's Soul Trap. (1 Sec Cooldown)"
WordHunterWoW_ENDesc_Item[109226] = "Use: Restores 3 health and 1 mana. (5 Min Cooldown)"
WordHunterWoW_ENDesc_Item[109246] = "Use: Ensnare Gul'dan's soul, imprisoning him for return to Archmage Khadgar at Starfall Outpost. (20 Sec Cooldown)"
WordHunterWoW_ENDesc_Item[109253] = "+10 Draenor Mining Skill.\n+10 Draenor Herbalism Skill.\n+10 Draenor Skinning Skill."
WordHunterWoW_ENDesc_Item[109254] = "Use: Provides the plans needed to upgrade your Garrison Lumber Mill building to level 2.\n\nLevel 1\nAllows you to mark small trees in Draenor for harvest. Harvested Timber can be converted to work orders for garrison supplies.\n\nLevel 2\nAllows you to mark medium trees for additional Timber.\n\nLevel 3\nAllows you to mark large trees for even more Timber.\n (1 Sec Cooldown)"
WordHunterWoW_ENDesc_Item[109255] = "Use: Provides the plans needed to upgrade your Garrison Lumber Mill building to level 3.\n\nLevel 1\nAllows you to mark small trees in Draenor for harvest. Harvested Timber can be converted to work orders for garrison supplies.\n\nLevel 2\nAllows you to mark medium trees for additional Timber.\n\nLevel 3\nAllows you to mark large trees for even more Timber.\n (1 Sec Cooldown)"
WordHunterWoW_ENDesc_Item[109256] = "Use: Provides the plans needed to upgrade your Engineering Works building to level 2.\n\nLevel 1\nAllows the production of Engineering items and work orders.\n\nLevel 2\nAllows followers with the Engineering trait to work here, granting a unique bonus.  Also allows up to 14 work orders at one time.\n\nLevel 3\nUnlocks Engineering missions, and allows up to 21 work orders at one time.\n (1 Sec Cooldown)"
WordHunterWoW_ENDesc_Item[109257] = "Use: Provides the plans needed to upgrade your Engineering Works building to level 3.\n\nLevel 1\nAllows the production of Engineering items and work orders.\n\nLevel 2\nAllows followers with the Engineering trait to work here, granting a unique bonus.  Also allows up to 14 work orders at one time.\n\nLevel 3\nUnlocks Engineering missions, and allows up to 21 work orders at one time.\n (1 Sec Cooldown)"
WordHunterWoW_ENDesc_Item[109258] = "Use: Provides the plans needed to build an Engineering Works building in your Garrison.\n\nLevel 1\nAllows the production of Engineering items and work orders.\n\nLevel 2\nAllows followers with the Engineering trait to work here, granting a unique bonus.  Also allows up to 14 work orders at one time.\n\nLevel 3\nUnlocks Engineering missions, and allows up to 21 work orders at one time.\n (1 Sec Cooldown)"
WordHunterWoW_ENDesc_Item[109262] = "Equip: When you heal or deal damage you have a chance to increase your Strength, Agility, or Intellect by 23 for 15 sec.  Your highest stat is always chosen.\nEquip: Increases the effect that healing and mana potions have on the wearer by 40%.  This effect does not stack."
WordHunterWoW_ENDesc_Item[109558] = "Use: Teaches you Draenor Alchemy and a number of recipes."
WordHunterWoW_ENDesc_Item[109574] = "Use: Creates a portable mailbox for 5 min. (3 Hr Cooldown)"
WordHunterWoW_ENDesc_Item[109576] = "Use: Provides the plans needed to upgrade your Lunarfall Excavation to level 2.\n\nLevel 1\nAllows players to mine Draenic Stone from mineral nodes in Draenor. Draenic Stone can be converted to work orders for Draenor minerals.\n\nLevel 2\nAllows followers with the Mining trait to work here, granting a unique bonus.  Also opens a new mineshaft, granting access to additional mining nodes and allows up to 14 work orders at one time.\n\nLevel 3\nA final mineshaft allows access to rich mining nodes.  In addition, garrison guards will patrol your mine, keeping it clear of hostile goren. Also allows up to 21 work orders at one time.\n (1 Sec Cooldown)"
WordHunterWoW_ENDesc_Item[109577] = "Use: Provides the plans needed to upgrade your Herb Garden to level 2.\n\nLevel 1\nGrows Draenic Seeds into herbs each day and herbalism nodes are available in the garden.\n\nLevel 2\nAllows followers with the Herbalism trait to work here, granting a unique bonus.  Also increases the amount of herbs that can be harvested at the garden and allows up to 14 work orders at one time.\n\nLevel 3\nGrow a unique Draenor fruit tree in your garden that grants food buffs. Also allows up to 21 work orders at one time.\n (1 Sec Cooldown)"
WordHunterWoW_ENDesc_Item[109578] = "Use: Provides the plans needed to build the Garrison Fishing Shack.\n\nLevel 1\nAllows small Draenor fish to be caught in garrison waters and provides access to daily Fishing quests.\n\nLevel 2\nAllows medium Draenor fish to be caught in garrison waters.\n\nLevel 3\nAllows enormous Draenor fish to be caught in garrison waters.  Also grants you a chance to catch a unique fish that can be used to lure mysterious creatures onto the shore.\n (1 Sec Cooldown)"
WordHunterWoW_ENDesc_Item[109592] = "Use: Unlocks Corki's Prison."
WordHunterWoW_ENDesc_Item[109599] = "Use: Makes you immune to some annoyances.  Persists through death.  Lasts 12 hrs."
WordHunterWoW_ENDesc_Item[109602] = "Use: Teaches you how to summon this companion."
