WordHunterWoW_ENDesc_Item[112059] = "Use: Adds this toy to your Toy Box.\n\nCreates a spinning wormhole the Engineer can use to travel around Draenor. (4 Hr Cooldown)"
WordHunterWoW_ENDesc_Item[112087] = "Use: Discern wisdom from this ancient carving."
WordHunterWoW_ENDesc_Item[112090] = "Use: Reverses the imbiber's gender for a short time."
WordHunterWoW_ENDesc_Item[112091] = "Use: Throw a Smoke Grenade at a Gordunni Boulderthrower to mark it for destruction. (5 Sec Cooldown)"
WordHunterWoW_ENDesc_Item[112093] = "Use: Permanently enchants a melee weapon to sometimes bleed your enemy for 88 damage, plus an additional 264 damage over 6 sec.\n\nCannot be applied to items above level 120."
WordHunterWoW_ENDesc_Item[112095] = "Use: Restores 0 health over 21 sec.  Must remain seated while eating. (1 Sec Cooldown)"
WordHunterWoW_ENDesc_Item[112099] = "Use: Drink near Zellek's hut in Veil Akraz to enter the shadow realm."
WordHunterWoW_ENDesc_Item[112100] = "Use: Drink near Ishaal's hut in the Shadowglade to peer into the shadow realm."
WordHunterWoW_ENDesc_Item[112115] = "Use: Permanently enchants a melee weapon to sometimes increase Versatility by 30 for 15 sec. \n\nCannot be applied to items above level 120."
WordHunterWoW_ENDesc_Item[112154] = "Use: Reduces the cooldown of your Disengage in half. Can only be used while in Ashran."
