WordHunterWoW_ENDesc_Item[138726] = "Use: Discover the hidden power within at the forge in your class hall to empower your artifact. \n\nConsumes all available items of this type."
WordHunterWoW_ENDesc_Item[138727] = "Use: Reduce all damage taken by 20% for 12 sec. Only usable in battlegrounds. (5 Min Cooldown)"
WordHunterWoW_ENDesc_Item[138728] = "Use: Become invisible for 6 sec. Only usable in battlegrounds. (5 Min Cooldown)"
WordHunterWoW_ENDesc_Item[138729] = "Use: Increase your chance of detecting invisible or stealthed enemies for 30 sec. Only usable in battlegrounds. (5 Min Cooldown)"
WordHunterWoW_ENDesc_Item[138730] = "Equip: The goggles simulate the effects of alcohol. The effects can easily be dismissed by removing the goggles."
WordHunterWoW_ENDesc_Item[138731] = "Use: Set out a bushel of apples to feed your entire raid or party's mounts!\n\nRestores 5% health and 5% mana per second over 20 sec.  If you spend at least 10 seconds eating you will become well fed and the cast time of your mount spells will be reduced by 50% for 1 hour.\n\nOnly usable in Battlegrounds."
WordHunterWoW_ENDesc_Item[138733] = "Use: Envelops a Shadescale Flyeater in a temporal weirding, making them docile and drawing them to the caster for collection.  (6 Sec Cooldown)"
