WordHunterWoW_ENDesc_Item[140796] = "Equip: Your melee and ranged attacks have a chance to grant you a Fiery, Frost, or Arcane enchant for 20 sec."
WordHunterWoW_ENDesc_Item[140797] = "Use: Gain 28 Leech for 12 sec. (1 Min Cooldown)"
WordHunterWoW_ENDesc_Item[140798] = "Equip: Your ranged attacks and spells have a chance to unleash a Carrion Swarm to infect all enemies in a line in front of you, dealing 136 Shadow damage over 8 sec."
WordHunterWoW_ENDesc_Item[140799] = "Use: Unleash a colossal slam that always critically hits, dealing 193 Physical damage split amongst all nearby enemies. If you hit less than 3 targets, the cooldown of this ability is reduced by 15 seconds. (1 Min Cooldown)"
