WordHunterWoW_ENDesc_Item[140803] = "Equip: Your healing spells have a chance to increase your Mastery, Haste, or Critical Strike by 25 for 8 sec."
WordHunterWoW_ENDesc_Item[140804] = "Equip: Your damaging spells have a chance to hurl a meteor from the Twisting Nether, causing 35 Spellfire damage to your target and nearby enemies."
