WordHunterWoW_ENDesc_Item[142334] = "Use: Restores up to 5% of your maximum health and mana every second over 20 sec. Must remain seated while eating.\n\nIf you spend at least 10 seconds eating you will become well fed and gain movement and attack speed for a short time after killing an enemy. Only usable in the Broken Isles. (1 Sec Cooldown)"
WordHunterWoW_ENDesc_Item[142341] = "Use: Adds this toy to your Toy Box.\n\nSummon your Love Boat on the water's surface within 20 yards.\nCooldown reduced during Love is in the Air. (30 Min Cooldown)"
WordHunterWoW_ENDesc_Item[142352] = "Use: Combine a Core of Bael'Gar, Core of Roccor, Essence of Incendius and Essence of Magmus into a Blackrock Ruby at the Black Forge in Blackrock Depths."
WordHunterWoW_ENDesc_Item[142353] = "Use: Combine a Core of Bael'Gar, Core of Roccor, Essence of Incendius and Essence of Magmus into a Blackrock Ruby at the Black Forge in Blackrock Depths."
